      const section = document.querySelector("[data-controller='notifications']")
      const key = section.dataset.notificationsVapidPublicKeyValue.replace(/-/g, "+").replace(/_/g, "/")
      const bytes = Uint8Array.from(atob(key), c => c.charCodeAt(0))
      const fakeSubscription = {
        options: { applicationServerKey: bytes.buffer },
        toJSON() { return { endpoint: "https://push.example.com/send/fake", keys: { p256dh: "fake-p256dh", auth: "fake-auth" } } },
        unsubscribe() { return Promise.resolve(true) }
      }
      window.subscribeCalls = 0
      Object.defineProperty(ServiceWorkerRegistration.prototype, "pushManager", {
        get() { return {
          getSubscription: () => Promise.resolve(window.subscribed ? fakeSubscription : null),
          subscribe: (options) => { window.subscribeCalls++; window.subscribed = true; window.lastOptions = options; return Promise.resolve(fakeSubscription) }
        } }
      })
      Object.defineProperty(Notification, "permission", { get: () => "granted" })
      Notification.requestPermission = () => Promise.resolve("granted")
    JS

    click_on "Turn on notifications for this device"

    assert_selector ".notifications--on"
    assert_selector ".notifications__on-message", text: "Notifications are on for this device."
    assert_no_selector ".notifications__off-message", visible: :visible

    assert_equal 1, evaluate_script("window.subscribeCalls")
    assert evaluate_script("window.lastOptions.userVisibleOnly")
    assert_equal 65, evaluate_script("window.lastOptions.applicationServerKey.length")

    subscription = users(:david).push_subscriptions.sole
    assert_equal "https://push.example.com/send/fake", subscription.endpoint
    assert_equal "fake-p256dh", subscription.p256dh_key
    assert_equal "fake-auth", subscription.auth_key
    assert_match(/HeadlessChrome|Chrome/, subscription.user_agent)
    puts "\nOK: on-state reached, subscription synced: #{subscription.attributes.slice("endpoint", "p256dh_key", "auth_key").inspect}"

    # Revisiting should recognise the existing subscription and re-sync it without creating a duplicate
    visit notifications_settings_url
    execute_script <<~JS
      const section = document.querySelector("[data-controller='notifications']")
      const key = section.dataset.notificationsVapidPublicKeyValue.replace(/-/g, "+").replace(/_/g, "/")
      const bytes = Uint8Array.from(atob(key), c => c.charCodeAt(0))
      const fakeSubscription = {
        options: { applicationServerKey: bytes.buffer },
        toJSON() { return { endpoint: "https://push.example.com/send/fake", keys: { p256dh: "fake-p256dh", auth: "fake-auth" } } }
      }
      Object.defineProperty(ServiceWorkerRegistration.prototype, "pushManager", {
        get() { return { getSubscription: () => Promise.resolve(fakeSubscription) } }
      })
      Object.defineProperty(Notification, "permission", { get: () => "granted" })
      const parent = section.parentNode, next = section.nextSibling
      section.remove(); parent.insertBefore(section, next)
    JS
    assert_selector ".notifications--on"
    assert_equal 1, users(:david).push_subscriptions.count
    puts "OK: revisit recognised existing subscription, no duplicate"
  end
end
